put["response_nonzero_despite_zero_integral",pp==-2 k y&&Integrate[pp,{y,-1,1}]==0&&Simplify[pp!=0,Assumptions->k>0&&y>0]];
mu=Integrate[chi pp,{y,-1,1}];
