h[s_]=a0+a1 s+a2 s^2+a3 s^3+a4 s^4;
hr[f_,s_]:=Module[{v},Integrate[f/.s->v,{v,0,s}]-s Integrate[f,{s,0,1}]];
put["trace_antifield_relative_primitive_identity",Expand[hr[D[h[s],s],s]-(h[s]-(1-s)h[0]-s h[1])]==0];
ee[s_,t_]=Sum[e[i,j]s^i t^j,{i,0,4},{j,0,3}];
qq[s_,t_]=Sum[q[i,j]s^i t^j,{i,0,3},{j,0,2}];
xx=ee[s,t]-(1-s)ee[0,t]-s ee[1,t];
uu=qq[s,t]-(1-s)qq[0,t]-s qq[1,t];
qeta=D[D[ee[s,t],t]-qq[s,t],s];
put["source_p_antifield_maps_off_shell",Expand[hr[qeta,s]-(D[xx,t]-uu)]==0];
put["source_variables_keep_both_spatial_endpoints",Expand[(xx/.s->0)]==0&&Expand[(xx/.s->1)]==0&&Expand[(uu/.s->0)]==0&&Expand[(uu/.s->1)]==0];
(* General local transgression identities, before spatial integration. *)
aone={f[x,y,t],g[x,y,t]}; at=atf[x,y,t]; hh=hfun[x,y];
curlA=D[aone[[2]],x]-D[aone[[1]],y];
etaQ={D[aone[[1]],t]-D[at,x],D[aone[[2]],t]-D[at,y]};
xQdens=etaQ[[1]]D[hh,y]-etaQ[[2]]D[hh,x];
fluxT=D[hh D[aone[[2]],t],x]-D[hh D[aone[[1]],t],y];
fluxAt=D[at D[hh,y],x]-D[at D[hh,x],y];
put["projected_antifield_Q_identity_with_all_divergences",Expand[xQdens-hh D[curlA,t]+fluxT+fluxAt]==0];

lag=-1/2(aa gdot-bb fdot)+tt(gx-fy);
subs={aa->f[x,y,t],bb->g[x,y,t],tt->atf[x,y,t],gdot->D[g[x,y,t],t],fdot->D[f[x,y,t],t],gx->D[g[x,y,t],x],fy->D[f[x,y,t],y]};
elax=(D[lag,aa]/.subs)-D[D[lag,fdot]/.subs,t]-D[D[lag,fy]/.subs,y];
elay=(D[lag,bb]/.subs)-D[D[lag,gdot]/.subs,t]-D[D[lag,gx]/.subs,x];
elat=D[lag,tt]/.subs;
put["canonical_component_antifield_normalizations",Expand[elax+D[g[x,y,t],t]-D[atf[x,y,t],y]]==0&&Expand[elay-D[f[x,y,t],t]+D[atf[x,y,t],x]]==0&&Expand[elat-curlA]==0];

